CREATE TABLE IF NOT EXISTS settings (id INTEGER PRIMARY KEY CHECK(id=1), name TEXT, institution TEXT, semester INTEGER);
CREATE TABLE IF NOT EXISTS semesters(id INTEGER PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'pending',created TEXT NOT NULL,semester INTEGER REFERENCES semesters(id),accounttype TEXT NOT NULL DEFAULT 'student' CHECK(accounttype IN ('student','teacher')));
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,userId TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS auth_failures(identity TEXT PRIMARY KEY,attempts INTEGER NOT NULL,reset INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS subjects(id TEXT PRIMARY KEY,semester INTEGER REFERENCES semesters(id),name TEXT NOT NULL,code TEXT NOT NULL DEFAULT '',description TEXT NOT NULL DEFAULT '',color TEXT NOT NULL DEFAULT 'sage');
CREATE TABLE IF NOT EXISTS notes(id TEXT PRIMARY KEY,subjectId TEXT NOT NULL REFERENCES subjects(id) ON DELETE CASCADE,title TEXT NOT NULL,content TEXT NOT NULL DEFAULT '',filename TEXT,originalName TEXT,mime TEXT,size INTEGER DEFAULT 0,authorId TEXT NOT NULL REFERENCES users(id),created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notices(id TEXT PRIMARY KEY,semester INTEGER REFERENCES semesters(id),title TEXT NOT NULL,content TEXT NOT NULL,category TEXT NOT NULL,pinned INTEGER NOT NULL DEFAULT 0,authorId TEXT REFERENCES users(id),created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS threads(id TEXT PRIMARY KEY,semester INTEGER REFERENCES semesters(id),title TEXT NOT NULL,content TEXT NOT NULL,authorId TEXT REFERENCES users(id),created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS replies(id TEXT PRIMARY KEY,threadId TEXT REFERENCES threads(id) ON DELETE CASCADE,content TEXT NOT NULL,authorId TEXT REFERENCES users(id),created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,semester INTEGER REFERENCES semesters(id),title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',date TEXT NOT NULL,kind TEXT NOT NULL,location TEXT NOT NULL DEFAULT '',authorId TEXT REFERENCES users(id));
CREATE TABLE IF NOT EXISTS routines(semester INTEGER NOT NULL REFERENCES semesters(id),kind TEXT NOT NULL CHECK(kind IN('class','exam')),content TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),updated TEXT NOT NULL,PRIMARY KEY(semester,kind));
